//! `ukiryu::tool_loader` against `Ukiryu::Tool::Loader` from the pinned Ruby
//! source (ukiryu ab6df353).
//!
//! Golden data: `fixtures/tool_loader/reference.json`, regenerated by
//! `fixtures/tool_loader/capture-loader.rb`. It holds three groups:
//!
//! * `transforms`: the loader's Hash helpers with the caller's arguments
//!   before and after each call (in-place mutation is part of the contract)
//!   and the result or the exception class and message;
//! * `conversions`: `convert_to_tool_definition` over every version file of
//!   the register fixture (`fixtures/register/spec`, a byte copy of the
//!   pinned spec/fixtures/register) for each distinct profile choice;
//! * `loads` and `synthetic`: `load_with_implementation_index` end to end
//!   over the register fixture and over small registers whose files are
//!   recorded in the reference. Detection commands were answered from the
//!   recorded tables; this test replays them through a scripted
//!   `CommandRunner` and compares every request the loader makes.
//!
//! Every Hash in the reference is an ordered `$map`, so key order and
//! Symbol/String keys are compared exactly for the helper results. Built
//! definitions are compared through `to_hash`, as the model tests do.
#[path = "models_data/support.rs"]
mod support;

use serde_json::{json, Value as Json};
use std::fs;
use std::path::{Path, PathBuf};
use ukiryu::executable::Platform;
use ukiryu::models::{Model, ToolDefinition, Value};
use ukiryu::register::Register;
use ukiryu::runtime::ShellName;
use ukiryu::tool::{self, DefinitionSource, ToolCache, ToolError, ToolOptions};
use ukiryu::tool_loader::{self, LoadError, LoadOptions, RegisterSource};
use ukiryu::version_detection::{CommandOutput, CommandRequest, CommandRunner, RunnerError};

const SOURCE: &str = "ab6df353c6dc2d7faf7817a86aafcafa82579896";

fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("workspace root")
        .to_path_buf()
}

fn reference() -> Json {
    let text = fs::read_to_string(repo_root().join("fixtures/tool_loader/reference.json"))
        .expect("reference.json");
    let data: Json = serde_json::from_str(&text).expect("reference json");
    assert_eq!(data["source"].as_str(), Some(SOURCE));
    data
}

/// Inverse of the capture encoder (`$sym`, `$float`, ordered `$map`).
fn dec(j: &Json) -> Value {
    match j {
        Json::Null => Value::Nil,
        Json::Bool(b) => Value::Bool(*b),
        Json::Number(n) => Value::int(n.as_i64().expect("integer")),
        Json::String(s) => Value::str(s.clone()),
        Json::Array(items) => Value::Array(items.iter().map(dec).collect()),
        Json::Object(m) => {
            if let Some(s) = m.get("$sym") {
                return Value::sym(s.as_str().expect("symbol"));
            }
            if let Some(f) = m.get("$float") {
                return Value::Float(f.as_str().expect("float").parse().expect("float"));
            }
            let pairs = m.get("$map").and_then(Json::as_array).expect("$map");
            Value::Hash(pairs.iter().map(|p| (dec(&p[0]), dec(&p[1]))).collect())
        }
    }
}

struct Check {
    failures: Vec<String>,
    passed: usize,
}

impl Check {
    fn new() -> Check {
        Check {
            failures: Vec::new(),
            passed: 0,
        }
    }

    fn eq<T: PartialEq + std::fmt::Debug>(&mut self, what: &str, expected: T, actual: T) {
        if expected == actual {
            self.passed += 1;
        } else {
            self.failures.push(format!(
                "{what}\n  expected {expected:?}\n  actual   {actual:?}"
            ));
        }
    }

    fn error(&mut self, what: &str, expected: &Json, actual: &LoadError) {
        self.eq(
            what,
            (
                expected["class"].as_str().unwrap_or_default().to_string(),
                expected["message"].as_str().unwrap_or_default().to_string(),
            ),
            (actual.class_name().to_string(), actual.message()),
        );
    }

    fn finish(self, name: &str) {
        let n = self.failures.len();
        assert!(
            n == 0,
            "{name}: {n} mismatches ({} passed)\n{}",
            self.passed,
            self.failures
                .iter()
                .take(25)
                .cloned()
                .collect::<Vec<_>>()
                .join("\n")
        );
        eprintln!("{name}: {} checks passed", self.passed);
    }
}

/// A definition as the model tests compare it: `to_hash` through the oracle
/// encoder (String-keyed Hashes as JSON objects).
fn definition_json(hash: &Value) -> Json {
    support::enc(hash)
}

fn check_definition(
    c: &mut Check,
    what: &str,
    data: &Json,
    expected: &Json,
    actual: Result<Option<ToolDefinition>, LoadError>,
) {
    match (expected.get("ok"), actual) {
        (Some(Json::Null), Ok(None)) => c.passed += 1,
        (Some(Json::String(key)), Ok(Some(tool))) => {
            let want = definition_json(&dec(&data["definitions"][key.as_str()]));
            let got = definition_json(&tool.to_hash().expect("to_hash"));
            c.eq(what, want, got);
        }
        (None, Err(e)) => c.error(what, &expected["error"], &e),
        (_, actual) => c.failures.push(format!(
            "{what}\n  expected {expected}\n  actual   {}",
            match actual {
                Ok(None) => "nil".to_string(),
                Ok(Some(t)) => format!("definition {:?}", t.name),
                Err(e) => e.to_string(),
            }
        )),
    }
}

#[test]
fn hash_helpers_match_the_source() {
    let data = reference();
    let rows = data["transforms"].as_array().expect("transforms");
    assert_eq!(rows.len(), 73);
    let mut c = Check::new();
    let mut errors = 0;
    let mut mutated = 0;
    for row in rows {
        let id = row["id"].as_str().unwrap();
        let Value::Array(mut args) = dec(&row["before"]) else {
            panic!("{id}: arguments")
        };
        let result = match row["method"].as_str().unwrap() {
            "deep_merge_hashes" => tool_loader::deep_merge_hashes(&args[0], &args[1]),
            "convert_actions_to_array" => {
                tool_loader::convert_actions_to_array(&mut args[0]).map(Value::Array)
            }
            "build_interface_commands_hash" => {
                tool_loader::build_interface_commands_hash(&mut args[0])
            }
            "flatten_signature" => tool_loader::flatten_signature(&mut args[0]),
            "extract_profile_data" => tool_loader::extract_profile_data(&args[0]),
            other => panic!("{id}: method {other}"),
        };
        match (row["result"].get("ok"), result) {
            (Some(expected), Ok(actual)) => c.eq(id, dec(expected), actual),
            (None, Err(e)) => {
                errors += 1;
                c.error(id, &row["result"]["error"], &e);
            }
            (_, actual) => c
                .failures
                .push(format!("{id}: expected {} got {actual:?}", row["result"])),
        }
        if row["before"] != row["after"] {
            mutated += 1;
        }
        c.eq(
            &format!("{id} caller after"),
            dec(&row["after"]),
            Value::Array(args),
        );
    }
    assert_eq!((errors, mutated), (17, 18));
    c.finish("hash_helpers_match_the_source");
}

fn fixture_register() -> Register {
    Register::at(repo_root().join("fixtures/register/spec"))
}

#[test]
fn conversion_over_register_fixtures() {
    let data = reference();
    let rows = data["conversions"].as_array().expect("conversions");
    assert_eq!(rows.len(), 96);
    let register = fixture_register();
    let mut c = Check::new();
    let mut built = 0;
    for row in rows {
        let s = |k: &str| row[k].as_str().unwrap().to_string();
        let (tool, implementation, file) = (s("tool"), s("implementation"), s("file"));
        let what = format!(
            "{tool}/{implementation}/{file} {}/{} detected={}",
            s("platform"),
            s("shell"),
            row["detected"]
        );
        let index = tool_loader::load_implementation_index(&register, &tool)
            .expect("index")
            .expect("index document");
        let interface = tool_loader::load_interface(&register, &index.interface.to_ruby_s())
            .expect("interface")
            .expect("interface document");
        let version =
            tool_loader::load_implementation_version(&register, &tool, &implementation, &file)
                .expect("version")
                .expect("version document");
        let actual = tool_loader::convert_to_tool_definition(
            &tool,
            &interface,
            &version,
            Some(&implementation),
            row["detected"].as_str(),
            &s("platform"),
            &s("shell"),
        );
        if matches!(actual, Ok(Some(_))) {
            built += 1;
        }
        check_definition(&mut c, &what, &data, &row["result"], actual);
    }
    assert_eq!(built, 64);
    c.finish("conversion_over_register_fixtures");
}

/// Answers detection commands from a recorded table; anything else fails
/// to spawn, as the capture's executor did.
struct ScriptedRunner<'a> {
    table: &'a Json,
    requests: Vec<CommandRequest>,
}

impl CommandRunner for ScriptedRunner<'_> {
    fn run(&mut self, request: &CommandRequest) -> Result<CommandOutput, RunnerError> {
        self.requests.push(request.clone());
        let mut line = vec![request.executable.clone()];
        line.extend(request.args.iter().cloned());
        let answer = &self.table[line.join(" ")];
        if answer.is_null() {
            return Err(RunnerError::new(format!(
                "No such file or directory - {}",
                request.executable
            )));
        }
        Ok(CommandOutput {
            stdout: answer["stdout"].as_str().unwrap().as_bytes().to_vec(),
            stderr: answer["stderr"].as_str().unwrap().as_bytes().to_vec(),
            exit_status: answer["status"].as_i64().unwrap() as i32,
        })
    }
}

fn request_json(r: &CommandRequest) -> Json {
    json!({
        "executable": r.executable,
        "args": r.args,
        "shell": r.shell,
        "timeout": r.timeout_secs,
        "allow_failure": r.allow_failure,
    })
}

fn replay_load(
    c: &mut Check,
    data: &Json,
    tables: &Json,
    register: &Register,
    row: &Json,
    label: &str,
) -> Option<bool> {
    let s = |k: &str| row[k].as_str().map(str::to_string);
    let tool = s("tool").unwrap();
    let what = format!(
        "{label} {tool} current={} platform={:?} shell={} table={}",
        s("current").unwrap(),
        s("platform"),
        s("shell").unwrap(),
        s("table").unwrap()
    );
    let mut runner = ScriptedRunner {
        table: &tables[s("table").unwrap()],
        requests: Vec::new(),
    };
    let current = s("current").unwrap();
    let platform = s("platform");
    let shell = s("shell").unwrap();
    let options = LoadOptions {
        current_platform: &current,
        platform: platform.as_deref(),
        shell: &shell,
        executable: None,
    };
    let actual = tool_loader::load_definition(register, &tool, &options, &mut runner);
    let outcome = match &actual {
        Ok(Some(_)) => Some(true),
        Ok(None) => Some(false),
        Err(_) => None,
    };
    let calls: Vec<Json> = runner.requests.iter().map(request_json).collect();
    c.eq(
        &format!("{what} detection requests"),
        row["calls"].clone(),
        Json::Array(calls),
    );
    check_definition(c, &what, data, &row["result"], actual);
    outcome
}

#[test]
fn loads_over_register_fixtures() {
    let data = reference();
    let rows = data["loads"].as_array().expect("loads");
    assert_eq!(rows.len(), 418);
    let register = fixture_register();
    let mut c = Check::new();
    let mut counts = (0, 0, 0);
    for row in rows {
        match replay_load(&mut c, &data, &data["tables"], &register, row, "fixture") {
            Some(true) => counts.0 += 1,
            Some(false) => counts.1 += 1,
            None => counts.2 += 1,
        }
    }
    assert_eq!(counts, (312, 106, 0));
    c.finish("loads_over_register_fixtures");
}

/// A scratch register written from the recorded files; removed afterwards.
struct ScratchRegister {
    dir: PathBuf,
}

impl ScratchRegister {
    fn new(name: &str, files: &Json) -> ScratchRegister {
        let dir =
            std::env::temp_dir().join(format!("ukiryu-tool-loader-{}-{name}", std::process::id()));
        assert!(!dir.exists(), "scratch {} already exists", dir.display());
        for (rel, text) in files.as_object().expect("files") {
            let path = dir.join(rel);
            fs::create_dir_all(path.parent().unwrap()).unwrap();
            fs::write(&path, text.as_str().unwrap()).unwrap();
        }
        ScratchRegister { dir }
    }
}

impl Drop for ScratchRegister {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.dir);
    }
}

#[test]
fn loads_over_synthetic_registers() {
    let data = reference();
    let registers = data["synthetic"].as_array().expect("synthetic");
    assert_eq!(registers.len(), 11);
    let mut c = Check::new();
    let mut counts = (0, 0, 0);
    let mut rows = 0;
    for entry in registers {
        let name = entry["name"].as_str().unwrap();
        let scratch = ScratchRegister::new(name, &entry["files"]);
        let register = Register::at(&scratch.dir);
        for row in entry["loads"].as_array().unwrap() {
            rows += 1;
            match replay_load(
                &mut c,
                &data,
                &data["synthetic_tables"],
                &register,
                row,
                name,
            ) {
                Some(true) => counts.0 += 1,
                Some(false) => counts.1 += 1,
                None => counts.2 += 1,
            }
        }
    }
    assert_eq!(rows, 231);
    assert_eq!(counts, (61, 82, 88));
    c.finish("loads_over_synthetic_registers");
}

/// Detection that never finds anything: every command fails to spawn.
struct NoCommands;

impl CommandRunner for NoCommands {
    fn run(&mut self, request: &CommandRequest) -> Result<CommandOutput, RunnerError> {
        Err(RunnerError::new(format!(
            "No such file or directory - {}",
            request.executable
        )))
    }
}

fn shell_named(name: &str) -> ShellName {
    ShellName::ALL
        .iter()
        .copied()
        .find(|s| s.as_str() == name)
        .unwrap_or_else(|| panic!("shell {name}"))
}

/// The register rows of the tool runtime's oracle
/// (`tests/tool_runtime_data/oracle.json`, `Tool.get` on a Linux host with
/// every detection command failing) through [`RegisterSource`]: tools Ruby
/// could not load are `ToolNotFoundError` from `tool::get`, and every other
/// row gets the definition Ruby built (`loaded.profile.to_yaml`).
#[test]
fn register_source_serves_the_tool_runtime() {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/tool_runtime_data/oracle.json");
    let oracle: Json = serde_json::from_str(&fs::read_to_string(path).unwrap()).unwrap();
    assert_eq!(oracle["oracle"].as_str(), Some(SOURCE));
    let rows = oracle["register"].as_array().expect("register rows");
    assert_eq!(rows.len(), 84);
    let source = RegisterSource::new(fixture_register(), Platform::Linux, NoCommands);
    let mut c = Check::new();
    let (mut missing, mut built) = (0, 0);
    for row in rows {
        let name = row["tool"].as_str().unwrap();
        let platform = row["platform"].as_str().unwrap();
        let what = format!("{name} {platform}/{}", row["shell"].as_str().unwrap());
        let options = ToolOptions::new(
            Platform::from_name(platform).unwrap(),
            shell_named(row["shell"].as_str().unwrap()),
        );
        if let Some(error) = row.get("load_error") {
            missing += 1;
            let cache = ToolCache::new();
            match tool::get(&source, &cache, name, &options) {
                Err(e @ ToolError::NotFound { .. }) => c.eq(
                    &what,
                    error["message"].as_str().unwrap().to_string(),
                    e.to_string(),
                ),
                other => c.failures.push(format!(
                    "{what}: expected ToolNotFoundError, got {:?}",
                    other.map(|t| t.name())
                )),
            }
            continue;
        }
        built += 1;
        match source.load_definition(name, &options) {
            Ok(Some(definition)) => {
                let want = oracle["definitions"][row["definition_yaml"].as_str().unwrap()]
                    .as_str()
                    .unwrap();
                let got = definition.to_yaml().expect("to_yaml");
                if support::yaml_equiv(want, &got) {
                    c.passed += 1;
                } else {
                    c.failures
                        .push(format!("{what}\n  expected {want:?}\n  actual   {got:?}"));
                }
            }
            other => c
                .failures
                .push(format!("{what}: expected a definition, got {other:?}")),
        }
    }
    assert_eq!((missing, built), (18, 66));
    c.finish("register_source_serves_the_tool_runtime");
}
